import {NEIGHBORS,connectionCandidates,signDeal,cancelDeal} from './region.js?v=university-neighborhood-1';
export {NEIGHBORS};
export const DEAL_RESULTS={created:'Contract created',alreadyActive:'Matching contract already active; existing terms kept',ended:'Contract ended',alreadyInactive:'No matching contract to end',missingConnection:'No registered, working connection for this resource',conflictingDeal:'Another contract occupies this neighbor/resource pair',unavailableSupply:'The neighbor cannot supply this offer'};
const successful=new Set(['created','alreadyActive','ended','alreadyInactive']);
export function validateNeighborDealAction(a){if(!Object.hasOwn(NEIGHBORS,a.neighbor)||!['power','water','garbage'].includes(a.resource)||a.neighbor==='sea'&&a.resource!=='garbage'||!['import','export'].includes(a.direction)||!['enable','disable'].includes(a.operation)||a.operation==='enable'&&![25,50,100].includes(a.amount))throw Error('Choose a neighbor, supported resource, direction and contract amount (25, 50 or 100).');return{neighbor:a.neighbor,resource:a.resource,direction:a.direction,operation:a.operation,...(a.operation==='enable'?{amount:a.amount}:{})};}
export function executeNeighborDeal(c,input){const a=validateNeighborDealAction(input),result=(outcome,dealId=null,fee=0)=>({ok:successful.has(outcome),dealResult:{outcome,dealId,fee}}),existing=c.region.deals.find(d=>d.kind===a.resource&&c.region.connections[d.connection]?.side===a.neighbor);
 if(a.operation==='disable'){if(!existing||existing.direction!==a.direction)return result('alreadyInactive');const ended=cancelDeal(c,existing.id);return result('ended',existing.id,ended.fee);}
 const available=connectionCandidates(c),live=con=>available.some(p=>p.tile===con.tile&&p.kind===con.kind&&p.side===con.side);
 if(existing){if(existing.direction===a.direction&&!existing.failed&&live(c.region.connections[existing.connection]))return result('alreadyActive',existing.id);return result('conflictingDeal');}
 const index=c.region.connections.findIndex(p=>p.side===a.neighbor&&(a.resource==='garbage'?['road','rail','highway','seaport'].includes(p.kind):p.kind===a.resource)&&live(p));if(index<0)return result('missingConnection');
 const accepted=signDeal(c,index,a.resource,a.direction,a.amount);return accepted.ok?result('created',c.region.deals.at(-1).id):result('unavailableSupply');
}
export function validateNeighborDealResult(v,action,status){const allowed=action.operation==='enable'?['created','alreadyActive','missingConnection','conflictingDeal','unavailableSupply']:['ended','alreadyInactive'];if(!v||!allowed.includes(v.outcome)||status!==(successful.has(v.outcome)?'triggered':'skipped')||(['created','alreadyActive','ended'].includes(v.outcome)?!Number.isSafeInteger(v.dealId)||v.dealId<1:v.dealId!==null)||!Number.isSafeInteger(v.fee)||v.fee<0||v.fee>1e9||v.outcome!=='ended'&&v.fee!==0)throw Error('Invalid scripted neighbor-deal history.');return{outcome:v.outcome,dealId:v.dealId,fee:v.fee};}
export const neighborDealLabel=a=>`${a.operation==='enable'?'Enable':'Disable'} ${NEIGHBORS[a.neighbor]} ${a.direction} ${a.resource}${a.operation==='enable'?' · '+a.amount+' units':''}`;
export const neighborDealResultText=r=>`${DEAL_RESULTS[r.outcome]}${r.dealId===null?'':' · #'+r.dealId}${r.outcome==='ended'?' · Termination fee §'+r.fee.toLocaleString():''}`;
